# ================= ВЗРОСЛЫЕ СОБЫТИЯ =================
def adult_events_for(l):
    pool = []
    has_job = l.get("job_type") in ["civilian","police","military"]
    is_crim = l.get("job_type") == "criminal"

    if l["married"] and l["children"] > 0:
        pool.append({"id":"a_fam1","title":"👶 Кризис","text":"Денег не хватает.",
                     "choices":[{"text":"Вторую работу","p":0.7,"success":"work_extra","fail":"burnout"},{"text":"Семью","p":1,"success":"family_time","fail":"none"}]})
        pool.append({"id":"a_fam2","title":"🧸 Детский праздник","text":"Организовать праздник ребёнку.",
                     "choices":[{"text":"💵 Устроить","p":1,"success_effect":{"happiness":10,"relationships":8,"cash":-600,"text":"Ребёнок счастлив!"}},{"text":"Скромно","p":1,"success_effect":{"happiness":3,"cash":-100,"text":"Дома."}}]})
        pool.append({"id":"a_fam3","title":"🤒 Ребёнок заболел","text":"Высокая температура.",
                     "choices":[{"text":"💵 К врачу","p":1,"success_effect":{"happiness":3,"cash":-500,"text":"Лекарства."}},{"text":"Домашние средства","p":0.5,"success_effect":{"health":-3,"cash":-100,"text":"Обошлось."},"fail_effect":{"happiness":-10,"cash":-300,"text":"Стало хуже."}}]})
    if not l["married"] and 18 <= l["age"] < 50:
        pool.append({"id":"a_marry","title":"💍 Брак","text":"Партнёр предлагает жениться.",
                     "choices":[{"text":"Согласиться","p":0.8,"success":"marry","fail":"none"},{"text":"Отказаться","p":1,"success":"none","fail":"none"}]})
    if l["married"]:
        pool.append({"id":"a_div","title":"💔 Развод","text":"Супруг подаёт на развод.",
                     "choices":[{"text":"Смириться","p":1,"success":"divorce","fail":"none"}]})
        pool.append({"id":"a_affair","title":"💔 Подозрение в измене","text":"Странное поведение партнёра.",
                     "choices":[{"text":"Поговорить","p":0.5,"success_effect":{"relationships":8,"happiness":5,"text":"Разобрались."},"fail_effect":{"relationships":-20,"happiness":-15,"text":"Скандал."}},{"text":"Следить","p":0.4,"success_effect":{"happiness":-15,"relationships":-20,"text":"Правда — больно."},"fail_effect":{"happiness":-10,"relationships":-10,"text":"Ошибся."}}]})
        pool.append({"id":"a23","title":"🎂 Годовщина свадьбы","text":"Годовщина свадьбы.",
                     "choices":[{"text":"💵 Праздник","p":0.9,"success_effect":{"relationships":15,"happiness":10,"cash":-1000,"text":"Второй медовый месяц!"},"fail_effect":{"relationships":-5,"text":"Испортилось."}},{"text":"Скромно","p":1,"success_effect":{"relationships":5,"happiness":3,"text":"Тихо."}}]})

    # Криминальные будни для бандитов
    if is_crim:
        pool.append({"id":"crim_deal","title":"💼 Нелегальная сделка","text":"Босс поручает перевезти контрабанду.",
                     "choices":[{"text":"Взяться","p":0.7,"success_effect":{"dirty":3000,"career_xp":25,"happiness":5,"text":"Сделка закрыта чисто!"},"fail_effect":{"in_prison":2,"happiness":-20,"text":"Облава! 2 года тюрьмы."}},
                                {"text":"Отказаться","p":1,"success_effect":{"career_xp":-15,"relationships":-5,"text":"Босс недоволен."}}]})
        pool.append({"id":"crim_war","title":"🔫 Стрелка","text":"Конкуренты заходят на вашу территорию.",
                     "choices":[{"text":"Идти на разборку","p":0.6,"success_effect":{"dirty":2000,"career_xp":35,"happiness":10,"text":"Территория отстояна!"},"fail_effect":{"health":-25,"happiness":-10,"text":"Ранение в перестрелке."}},
                                {"text":"Отступить","p":1,"success_effect":{"career_xp":-25,"text":"Банда потеряла влияние."}}]})

